--
-- Name: execution_audit_journal; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.execution_audit_journal AS
 SELECT 'EXECUTION'::text AS source_system,
    (e.id)::text AS source_id,
    e.created_at AS occurred_at,
    e.severity,
    e.event_type,
    e.message,
    e.payload,
    c.command_id AS correlation_id,
    c.terminal_id,
    t.account_number,
    a.broker_name,
    a.server_name,
    c.environment,
    c.sandbox_mode
   FROM (((public.execution_command_events e
     JOIN public.execution_commands c ON ((c.command_id = e.command_id)))
     LEFT JOIN public.mt5_terminals t ON ((t.terminal_id = c.terminal_id)))
     LEFT JOIN public.trading_accounts a ON ((a.account_number = t.account_number)))
UNION ALL
 SELECT 'EA_COMM'::text AS source_system,
    (ev.id)::text AS source_id,
    ev.created_at AS occurred_at,
    ev.severity,
    ev.event_type,
    ev.message,
    ev.payload,
    COALESCE((ev.payload ->> 'commandId'::text), (ev.payload ->> 'intentId'::text), ev.terminal_id) AS correlation_id,
    ev.terminal_id,
    t.account_number,
    a.broker_name,
    a.server_name,
    NULL::text AS environment,
    NULL::boolean AS sandbox_mode
   FROM ((public.ea_comm_events ev
     LEFT JOIN public.mt5_terminals t ON ((t.terminal_id = ev.terminal_id)))
     LEFT JOIN public.trading_accounts a ON ((a.account_number = t.account_number)))
UNION ALL
 SELECT 'RISK'::text AS source_system,
    (r.id)::text AS source_id,
    r.created_at AS occurred_at,
        CASE
            WHEN r.allowed THEN 'INFO'::text
            ELSE 'WARNING'::text
        END AS severity,
    r.code AS event_type,
    r.message,
    jsonb_build_object('allowed', r.allowed, 'remainingDailyLossAmount', r.remaining_daily_loss_amount) AS payload,
    COALESCE(r.intent_id, r.account_number) AS correlation_id,
    NULL::text AS terminal_id,
    r.account_number,
    a.broker_name,
    a.server_name,
    NULL::text AS environment,
    NULL::boolean AS sandbox_mode
   FROM (public.risk_decisions r
     JOIN public.trading_accounts a ON ((a.account_number = r.account_number)));


